head.script:
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.checkValue = function(id, value) {
    if (WebSquare.wUnit.getDomById($p.id + id).textContent == value) {
        return true;
    }
    return false
}
scwin.checkInput = function(id, value) {
    if (WebSquare.wUnit.getDomById($p.id + id).value == value) {
        return true;
    }
    return false
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 'custom test0' 컬럼에 값('1234567.12')을 입력하고 enterkey를 실행한다.
    //1. After running the sample, enter the value ('1234567.12') in the 'custom test0' column and execute enterkey.
    //Verify step 1. The value '1234567.12' is entered and displayed.(Previously shown as '1234567.00.12' value)
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'grid2_cell_0_0')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_grid2__column2').setValue('1234567.12')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grid2_cell_0_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkValue($p.id+'grid2_cell_0_0', '1,234,567.12')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. test1 영역의 inputbox에 값('1234567')을 입력하고 enterkey를 실행한다.
    //2. Enter the value ('1234567') in the input box of the test1 area and execute enterkey.
    //Verify step 2. A value of '1234567.00' is entered and displayed.(Previously shown as '1234567.00.00' value)
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('input1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('input1').setValue('1234567')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkInput($p.id+'input1', '1,234,567.00')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. test2 영역의 inputbox에 값('1234567')을 입력하고 enterkey를 실행한다.
    //3. Enter the value ('1234567') in the input box of the test2 area and execute enterkey.
    //Verify step 3. A value of '1234567.00' is entered and displayed.(Previously shown as '1234567.00.00' value)
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('input2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('input2').setValue('1234567')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkInput($p.id+'input2', '1,234,567.00')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    grid1.setRef({
        ref: "vector",
        baseNode: "vector",
        repeatNode: "data"
    });
    grid1.insertRow();
    grid1.setCellInputType(0, 0, {
        inputType: "text",
        options: {
            dataType: "float",
            maxlength: "7.2",
            displayFormat: "#,###.#0",
            applyFormat: "all"
        }
    });
    grid1.setCellInputType(0, 1, {
        inputType: "text",
        options: {
            dataType: "float",
            maxlength: "7.2",
            displayFormat: "#,###",
            applyFormat: "all"
        }
    });
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 23-Feb-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
